#define MAX_ITERATIONS 100

#include <stdlib.h>
#include <string.h>

#include <openthread/instance.h>
#include <openthread/ip6.h>
#include <openthread/link.h>
#include <openthread/tasklet.h>
#include <openthread/thread.h>
#include <openthread/thread_ftd.h>
#include <openthread/platform/radio.h>

#include "common/code_utils.hpp"

extern "C" void FuzzerPlatformInit(void);
extern "C" void FuzzerPlatformProcess(otInstance *aInstance);

extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
{
    const otPanId panId = 0xdead;

    otInstance * instance = NULL;
    otRadioFrame frame;
    uint8_t *    buf = NULL;

    VerifyOrExit(size <= OT_RADIO_FRAME_MAX_SIZE);

    FuzzerPlatformInit();

    instance = otInstanceInitSingle();
    otLinkSetPanId(instance, panId);
    otIp6SetEnabled(instance, true);
    otThreadSetEnabled(instance, true);
    otThreadBecomeLeader(instance);

    buf = static_cast<uint8_t *>(malloc(size));

    memset(&frame, 0, sizeof(frame));
    frame.mPsdu    = buf;
    frame.mChannel = 11;
    frame.mLength  = static_cast<uint8_t>(size);

    memcpy(buf, data, frame.mLength);

    otPlatRadioReceiveDone(instance, &frame, OT_ERROR_NONE);

    for (int i = 0; i < MAX_ITERATIONS; i++)
    {
        while (otTaskletsArePending(instance))
        {
            otTaskletsProcess(instance);
        }

        FuzzerPlatformProcess(instance);
    }

exit:

    if (buf != NULL)
    {
        free(buf);
    }

    if (instance != NULL)
    {
        otInstanceFinalize(instance);
    }

    return 0;
}

